<?php
declare(strict_types=1);
require_once __DIR__ . '/../back-end/seguranca.php';
iniciar_sessao_segura();
if (empty($_SESSION['id'])) { header('Location: login.php?next=community', true, 302); exit; }
require_once __DIR__ . '/../community/back-end/bootstrap.php';
try {
    $user = comunidade_usuario($pdo, true);
    comunidade_garantir_tabela_termos($pdo);
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['community_terms_action'] ?? '') === 'accept') { csrf_exigir(); comunidade_registrar_aceite($pdo, (int)$user['id']); header('Location: comunidade.php', true, 303); exit; }
    $termsAccepted = comunidade_tem_aceite($pdo, (int)$user['id']) && !isset($_GET['terms']);
    if ($termsAccepted) {
        comunidade_instalar_schema($pdo);
        $stmt = $pdo->prepare('SELECT COUNT(*) FROM comunidade_publicacoes WHERE usuario_id = ?');
        $stmt->execute([$user['id']]);
        $user['posts_count'] = (int)$stmt->fetchColumn();
    } else {
        $user['posts_count'] = 0;
    }
    $themeStmt = $pdo->prepare('SELECT tema FROM usuarios WHERE id = ?');
    $themeStmt->execute([$user['id']]);
    $communityTheme = $themeStmt->fetchColumn();
    if (!in_array($communityTheme, ['claro', 'escuro', 'sistema'], true)) $communityTheme = 'sistema';
} catch (Throwable $e) {
    error_log('[community_page] Falha ao iniciar comunidade: ' . $e->getMessage());
    if ($e instanceof PDOException) tratar_erro_bd($e, 'community_page');
    http_response_code(500);
    echo 'Não foi possível iniciar a comunidade. Confira a conexão e as permissões do banco principal.';
    exit;
}
?>
